#include "audio_fir.h"

/* Generated by tools/gen_audio_fir.py: 97 taps, Kaiser beta 6.755, cut-off 8 kHz at 64 kHz, Q30,
   sum = 2^30 (unity DC gain). Flat to 6.5 kHz, -0.24 dB at 7 kHz, >= 75 dB from 9.5 kHz. */
static const int32_t k_coef[AFIR_TAPS] = {
  0, -58475, -120010, -117396, 0, 204380,
  368711, 326989, 0, -493851, -844117, -714728,
  0, 1000616, 1657109, 1363913, 0, -1818689,
  -2949114, -2381127, 0, 3070244, 4906320, 3909032,
  0, -4926311, -7796828, -6159744, 0, 7660882,
  12068575, 9503880, 0, -11801301, -18629528, -14734609,
  0, 18617977, 29816403, 24047192, 0, -32303769,
  -54252103, -46728719, 0, 79590865, 169984919, 241372918,
  268460812, 241372918, 169984919, 79590865, 0, -46728719,
  -54252103, -32303769, 0, 24047192, 29816403, 18617977,
  0, -14734609, -18629528, -11801301, 0, 9503880,
  12068575, 7660882, 0, -6159744, -7796828, -4926311,
  0, 3909032, 4906320, 3070244, 0, -2381127,
  -2949114, -1818689, 0, 1363913, 1657109, 1000616,
  0, -714728, -844117, -493851, 0, 326989,
  368711, 204380, 0, -117396, -120010, -58475,
  0,
};

#define CODE_MID 2048
#define COEF_Q 30
#define OUT_SHIFT 18 /* Q30 coefficients x code -> code x 2^12: one code = 4096 (24-bit scale) */
#define DC_SHIFT 10  /* a = 1 - 2^-10: ~2.5 Hz at 16 kHz */

void afir_reset(afir_t *f)
{
  f->head = 0u;
  f->primed = 0;
  f->dc_x1 = 0;
  f->dc_y1 = 0;
}

static void push(afir_t *f, int32_t x)
{
  f->hist[f->head] = x;
  f->hist[f->head + AFIR_TAPS] = x;
  f->head = (f->head + 1u == AFIR_TAPS) ? 0u : f->head + 1u;
}

/* Newest sample last: hist[head .. head + TAPS - 1] holds inputs oldest -> newest. */
static int32_t filter(const afir_t *f)
{
  const int32_t *h = &f->hist[f->head];
  int64_t acc = 0;
  for (uint32_t i = 0; i < AFIR_TAPS; i++) {
    acc += (int64_t)k_coef[i] * h[i];
  }
  return (int32_t)(acc >> OUT_SHIFT);
}

static int32_t dc_block(afir_t *f, int32_t x)
{
  int64_t y = (int64_t)x - f->dc_x1 + f->dc_y1 - ((f->dc_y1 + (1 << (DC_SHIFT - 1))) >> DC_SHIFT);
  f->dc_x1 = x;
  if (y > AFIR_OUT_MAX) {
    y = AFIR_OUT_MAX;
  } else if (y < -AFIR_OUT_MAX) {
    y = -AFIR_OUT_MAX;
  }
  f->dc_y1 = (int32_t)y;
  return (int32_t)y;
}

void afir_process(afir_t *f, const uint32_t *codes, size_t n, int32_t *out)
{
  if (n == 0u) {
    return;
  }
  if (!f->primed) {
    const int32_t x0 = (int32_t)(codes[0] & 0xFFFu) - CODE_MID;
    for (uint32_t i = 0; i < AFIR_TAPS; i++) {
      push(f, x0);
    }
    f->dc_x1 = x0 * (1 << (COEF_Q - OUT_SHIFT)); /* the FIR's steady output for x0: no step */
    f->dc_y1 = 0;
    f->primed = 1;
  }
  for (size_t i = 0; i < n; i++) {
    push(f, (int32_t)(codes[i] & 0xFFFu) - CODE_MID);
    if (i % AFIR_DECIM == 0u) {
      out[i / AFIR_DECIM] = dc_block(f, filter(f));
    }
  }
}
